-- 2. Replace the 3 workflow bodies with the full flows --------------------

-- Tanker Loading -- 22 states, matches customer spec
UPDATE workflow_definition SET body_json = '{"code":"M10.TankerOutbound","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT"},{"code":"GATE_PASS_CREATED","assignedRole":"ParkingSecurity"},{"code":"PARKING_IN_1","assignedRole":"Dispatch"},{"code":"DISPATCH_VEHICLE_ENTRY","assignedRole":"Planning"},{"code":"ORDER_SHEET_UPLOADED","assignedRole":"QC"},{"code":"QC_PRELOAD_APPROVED","assignedRole":"ParkingSecurity"},{"code":"QC_PRELOAD_REJECTED","terminal":true},{"code":"PARKING_OUT_1","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_1","assignedRole":"LoadingSupervisor"},{"code":"LOADING_IN_PROGRESS","assignedRole":"QC"},{"code":"QC_SAMPLE_APPROVED","assignedRole":"WeighmentOfficer"},{"code":"QC_SAMPLE_REJECTED","terminal":true},{"code":"WEIGHMENT_2","assignedRole":"ParkingSecurity"},{"code":"PARKING_IN_2","assignedRole":"Dispatch"},{"code":"WEIGHT_DIFF_OK","assignedRole":"BillingOfficer"},{"code":"WEIGHT_DIFF_PENDING_MANAGER","assignedRole":"Manager"},{"code":"BILLING_DONE","assignedRole":"WeighmentOfficer"},{"code":"PARKING_OUT_2","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_3","assignedRole":"Manager"},{"code":"READY_FOR_EXIT","assignedRole":"FrontGate"},{"code":"GATE_PASS_OUT_CLOSED","terminal":true},{"code":"REJECTED_BY_MANAGER","terminal":true}],"transitions":[{"from":"DRAFT","to":"GATE_PASS_CREATED","trigger":"page.submitted","pageCode":"pico:front-gate-create"},{"from":"GATE_PASS_CREATED","to":"PARKING_IN_1","trigger":"page.submitted","pageCode":"pico:parking-scan"},{"from":"PARKING_IN_1","to":"DISPATCH_VEHICLE_ENTRY","trigger":"page.submitted","pageCode":"pico:dispatch-vehicle-details"},{"from":"DISPATCH_VEHICLE_ENTRY","to":"ORDER_SHEET_UPLOADED","trigger":"page.submitted","pageCode":"pico:loading-order-sheet"},{"from":"ORDER_SHEET_UPLOADED","to":"QC_PRELOAD_APPROVED","trigger":"page.submitted","pageCode":"pico:qc-preload-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"ORDER_SHEET_UPLOADED","to":"QC_PRELOAD_REJECTED","trigger":"page.submitted","pageCode":"pico:qc-preload-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"QC_PRELOAD_APPROVED","to":"PARKING_OUT_1","trigger":"page.submitted","pageCode":"pico:parking-scan"},{"from":"PARKING_OUT_1","to":"WEIGHMENT_1","trigger":"page.submitted","pageCode":"pico:weighment-capture"},{"from":"WEIGHMENT_1","to":"LOADING_IN_PROGRESS","trigger":"page.submitted","pageCode":"pico:loading-in-progress"},{"from":"LOADING_IN_PROGRESS","to":"QC_SAMPLE_APPROVED","trigger":"page.submitted","pageCode":"pico:qc-final-out","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"LOADING_IN_PROGRESS","to":"QC_SAMPLE_REJECTED","trigger":"page.submitted","pageCode":"pico:qc-final-out","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"QC_SAMPLE_APPROVED","to":"WEIGHMENT_2","trigger":"page.submitted","pageCode":"pico:weighment-capture"},{"from":"WEIGHMENT_2","to":"PARKING_IN_2","trigger":"page.submitted","pageCode":"pico:parking-scan"},{"from":"PARKING_IN_2","to":"WEIGHT_DIFF_OK","trigger":"page.submitted","pageCode":"pico:weight-diff-entry","guard":"#submitted[''withinTolerance''] == ''YES''"},{"from":"PARKING_IN_2","to":"WEIGHT_DIFF_PENDING_MANAGER","trigger":"page.submitted","pageCode":"pico:weight-diff-entry","guard":"#submitted[''withinTolerance''] == ''NO''"},{"from":"WEIGHT_DIFF_PENDING_MANAGER","to":"WEIGHT_DIFF_OK","trigger":"page.submitted","pageCode":"pico:manager-qty-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"WEIGHT_DIFF_PENDING_MANAGER","to":"REJECTED_BY_MANAGER","trigger":"page.submitted","pageCode":"pico:manager-qty-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"WEIGHT_DIFF_OK","to":"BILLING_DONE","trigger":"page.submitted","pageCode":"pico:billing-entry"},{"from":"BILLING_DONE","to":"PARKING_OUT_2","trigger":"page.submitted","pageCode":"pico:parking-scan"},{"from":"PARKING_OUT_2","to":"WEIGHMENT_3","trigger":"page.submitted","pageCode":"pico:weighment-capture"},{"from":"WEIGHMENT_3","to":"READY_FOR_EXIT","trigger":"page.submitted","pageCode":"pico:manager-weight-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"WEIGHMENT_3","to":"REJECTED_BY_MANAGER","trigger":"page.submitted","pageCode":"pico:manager-weight-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"READY_FOR_EXIT","to":"GATE_PASS_OUT_CLOSED","trigger":"page.submitted","pageCode":"pico:gate-pass-out-closure"}]}' WHERE tenant_id=1 AND code='M10.TankerOutbound' AND version=1;

