UPDATE workflow_definition SET body_json = '{"code":"M10.PackLoading","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT"},{"code":"GATE_PASS_CREATED","assignedRole":"ParkingSecurity"},{"code":"PARKING_IN_1","assignedRole":"Dispatch"},{"code":"DISPATCH_VEHICLE_ENTRY","assignedRole":"QC"},{"code":"QC_PRELOAD_APPROVED","assignedRole":"Planning"},{"code":"QC_PRELOAD_REJECTED","terminal":true},{"code":"ORDER_SHEET_UPLOADED","assignedRole":"Dispatch"},{"code":"LOADING_ALLOCATED","assignedRole":"WeighmentOfficer"},{"code":"PARKING_OUT_1","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_1","assignedRole":"LoadingSupervisor"},{"code":"LOADING_IN_PROGRESS","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_2","assignedRole":"LoadingSupervisor"},{"code":"SEALING_DONE","assignedRole":"ParkingSecurity"},{"code":"PARKING_IN_2","assignedRole":"PMTTeam"},{"code":"PMT_CHECK_OK","assignedRole":"BillingOfficer"},{"code":"PMT_CAMERA_VERIFICATION","assignedRole":"PMTTeam"},{"code":"PMT_CHECK_PENDING_MANAGER","assignedRole":"Manager"},{"code":"RELOAD_REQUIRED","assignedRole":"LoadingSupervisor"},{"code":"BILLING_DONE","assignedRole":"WeighmentOfficer"},{"code":"PARKING_OUT_2","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_3","assignedRole":"Manager"},{"code":"READY_FOR_EXIT","assignedRole":"FrontGate"},{"code":"GATE_PASS_OUT_CLOSED","terminal":true},{"code":"REJECTED_BY_MANAGER","terminal":true}],"transitions":[{"from":"DRAFT","to":"GATE_PASS_CREATED","trigger":"page.submitted","pageCode":"pico:front-gate-create"},{"from":"GATE_PASS_CREATED","to":"PARKING_IN_1","trigger":"page.submitted","pageCode":"pico:parking-scan"},{"from":"PARKING_IN_1","to":"DISPATCH_VEHICLE_ENTRY","trigger":"page.submitted","pageCode":"pico:dispatch-vehicle-details"},{"from":"DISPATCH_VEHICLE_ENTRY","to":"QC_PRELOAD_APPROVED","trigger":"page.submitted","pageCode":"pico:qc-preload-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"DISPATCH_VEHICLE_ENTRY","to":"QC_PRELOAD_R