":"page.submitted","pageCode":"pico:billing-entry"},{"from":"BILLING_DONE","to":"PARKING_OUT_2","trigger":"page.submitted","pageCode":"pico:parking-scan"},{"from":"PARKING_OUT_2","to":"WEIGHMENT_3","trigger":"page.submitted","pageCode":"pico:weighment-capture"},{"from":"WEIGHMENT_3","to":"READY_FOR_EXIT","trigger":"page.submitted","pageCode":"pico:manager-weight-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"WEIGHMENT_3","to":"REJECTED_BY_MANAGER","trigger":"page.submitted","pageCode":"pico:manager-weight-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"READY_FOR_EXIT","to":"GATE_PASS_OUT_CLOSED","trigger":"page.submitted","pageCode":"pico:gate-pass-out-closure"}]}' WHERE tenant_id=1 AND code='M10.PackLoading' AND version=1;

